+	ret = swapon(self->swap_dev, 0);
+	err = errno;
+	ASSERT_EQ(ret, 0) {
+		TH_LOG("swapon(%s) failed: %s", self->swap_dev, strerror(err));
+		if (uffd >= 0)
+			close(uffd);
+		munmap(mem, self->pmd_size);
+	}
+
+	if (uffd >= 0)
+		close(uffd);
+	munmap(mem, self->pmd_size);
